using EddaStore.Models.Products; using EddaStore.Repositories.Interfaces; using EddaStore.Services.Interfaces; using Microsoft.AspNetCore.Hosting; using Microsoft.AspNetCore.Http;
namespace EddaStore.Services;
public class ProductImageService(IProductImageRepository repository, IProductRepository products, IWebHostEnvironment environment) : IProductImageService
{
    private static readonly HashSet<string> Allowed=[".jpg",".jpeg",".png",".webp"]; private const long MaxSize=5*1024*1024;
    public Task<IReadOnlyList<ProductImage>> GetAsync(Guid productId,CancellationToken ct=default)=>repository.GetByProductIdAsync(productId,ct);
    public async Task AddAsync(Guid productId,IReadOnlyList<IFormFile> files,CancellationToken ct=default){if(files.Count==0)return;if(await products.GetByIdAsync(productId,ct) is null)throw new KeyNotFoundException(); var dir=Path.Combine(environment.WebRootPath,"uploads","products",productId.ToString("N")); Directory.CreateDirectory(dir); var current=await repository.GetByProductIdAsync(productId,ct); var order=current.Count; foreach(var f in files){var ext=Path.GetExtension(f.FileName).ToLowerInvariant();if(f.Length==0||f.Length>MaxSize||!Allowed.Contains(ext)||!f.ContentType.StartsWith("image/",StringComparison.OrdinalIgnoreCase))throw new ArgumentException("يجب رفع صورة JPG أو PNG أو WEBP بحجم لا يتجاوز 5MB.");var name=$"{Guid.NewGuid():N}{ext}";var full=Path.Combine(dir,name);await using var stream=File.Create(full);await f.CopyToAsync(stream,ct);await repository.AddAsync(new ProductImage{ProductId=productId,ImageUrl=$"/uploads/products/{productId:N}/{name}",SortOrder=order++,IsPrimary=!current.Any()&&order==1},ct);}await repository.SaveChangesAsync(ct);}
    public async Task SetPrimaryAsync(Guid productId,Guid imageId,CancellationToken ct=default){var images=await repository.GetByProductIdAsync(productId,ct);if(!images.Any(x=>x.Id==imageId))throw new KeyNotFoundException();foreach(var image in images){var tracked=await repository.GetAsync(image.Id,ct);if(tracked is not null)tracked.IsPrimary=tracked.Id==imageId;}await repository.SaveChangesAsync(ct);}
    public async Task DeleteAsync(Guid productId,Guid imageId,CancellationToken ct=default){var image=await repository.GetAsync(imageId,ct);if(image is null||image.ProductId!=productId)throw new KeyNotFoundException();repository.Delete(image);await repository.SaveChangesAsync(ct);var path=Path.Combine(environment.WebRootPath,image.ImageUrl.TrimStart('/').Replace('/',Path.DirectorySeparatorChar));if(File.Exists(path))File.Delete(path);}
}
